Fix errors in this Unity test code.

Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"

// Forward declarations for dependencies
void quickSort(int arr[], int low, int high);

// Helper: Checks if an array is sorted in non-decreasing order
int helper_is_sorted(int* arr, int length) {
    for (int i = 1; i < length; ++i) {
        if (arr[i-1] > arr[i]) return 0;
    }
    return 1;
}

void setUp(void) { }
void tearDown(void) { }

void test_quickSort_low_not_less_than_high_noop(void) {
    int arr[] = {5, 3, 8, 1, 2};
    int original[] = {5, 3, 8, 1, 2};
    int n = sizeof(arr)/sizeof(arr[0]);

    // Case 1: low == high (single element, should do nothing)
    quickSort(arr, 2, 2);
    for (int i = 0; i < n; ++i) {
        TEST_ASSERT_EQUAL_INT(original[i], arr[i]);
    }

    // Case 2: low > high (invalid range, should do nothing)
    quickSort(arr, 4, 2);
    for (int i = 0; i < n; ++i) {
        TEST_ASSERT_EQUAL_INT(original[i], arr[i]);
    }
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(test_quickSort_low_not_less_than_high_noop);
    return UNITY_END();
}

